class ActionEntryDataView {
 public:
  using Tag = internal::ActionEntry_Data::ActionEntry_Tag;

  ActionEntryDataView() = default;

  ActionEntryDataView(
      internal::ActionEntry_Data* data,
      mojo::Message* message)
      : data_(data), message_(message) {}

  bool is_null() const {
    // For inlined unions, |data_| is always non-null. In that case we need to
    // check |data_->is_null()|.
    return !data_ || data_->is_null();
  }

  Tag tag() const { return data_->tag; }
  bool is_subheading() const { return data_->tag == Tag::kSubheading; }
  inline void GetSubheadingDataView(
      mojo::StringDataView* output) const;

  template <typename UserType>
  [[nodiscard]] bool ReadSubheading(UserType* output) const {
    
    CHECK(is_subheading());
    return mojo::internal::Deserialize<mojo::StringDataView>(
        data_->data.f_subheading.Get(), output, message_);
  }
  bool is_details() const { return data_->tag == Tag::kDetails; }
  inline void GetDetailsDataView(
      ActionDetailsDataView* output) const;

  template <typename UserType>
  [[nodiscard]] bool ReadDetails(UserType* output) const {
    
    CHECK(is_details());
    return mojo::internal::Deserialize<::ai_chat::mojom::ActionDetailsDataView>(
        data_->data.f_details.Get(), output, message_);
  }

 private:
  internal::ActionEntry_Data* data_ = nullptr;
  mojo::Message* message_ = nullptr;
};



